function getMimeType(p) {
  const ext = p.slice(p.lastIndexOf('.')).toLowerCase();
  const types = {
    '.html': 'text/html; charset=utf-8', '.js': 'application/javascript',
    '.css': 'text/css', '.svg': 'image/svg+xml', '.json': 'application/json',
    '.png': 'image/png', '.jpg': 'image/jpeg', '.ico': 'image/x-icon'
  };
  return types[ext] || 'application/octet-stream';
}

// --- Password protection helpers ---
const _pwdEncoder = _enc || new TextEncoder();

function passwordKey(key) { return KV_PREFIX + key + '.pwd'; }

function generateSalt() {
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  return btoa(String.fromCharCode(...bytes));
}

async function sha256Hex(saltB64, password) {
  const salt = Uint8Array.from(atob(saltB64), c => c.charCodeAt(0));
  const pwdBytes = _pwdEncoder.encode(password);
  const combined = new Uint8Array(salt.length + pwdBytes.length);
  combined.set(salt);
  combined.set(pwdBytes, salt.length);
  const hash = await crypto.subtle.digest('SHA-256', combined);
  return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');
}

// 恒定时间比较：避免因提前返回而泄露哈希前缀信息
// （Edge Functions 无现成实现，手写；长度不等时直接返回 false 可接受——哈希长度固定 64 字符 hex）
function constantTimeEqual(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

// --- 密码哈希版本化 ---
// v1（历史）: SHA-256(salt || password)，单轮，易被 GPU 暴力破解
// v2（当前）: PBKDF2-SHA256，10 万次迭代（官方支持 deriveBits 的三种算法之一：ECDH/HKDF/PBKDF2）
//   实测单次 100k 迭代约 12ms，远低于边缘函数 200ms CPU 上限
// 迁移策略：读取时按记录里的 v 选择算法；v1 记录校验通过后透明升级为 v2（复用原盐）。
//   因此存量密码无需重置，但也不能在校验失败时升级（避免污染元数据）。
const PASSWORD_VERSION = 2;
const PBKDF2_ITERATIONS = 100000;

async function pbkdf2Hex(saltB64, password, iterations) {
  const salt = Uint8Array.from(atob(saltB64), c => c.charCodeAt(0));
  const keyMaterial = await crypto.subtle.importKey('raw', _pwdEncoder.encode(password), 'PBKDF2', false, ['deriveBits']);
  const bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', salt, iterations: iterations || PBKDF2_ITERATIONS, hash: 'SHA-256' }, keyMaterial, 256);
  return Array.from(new Uint8Array(bits)).map(b => b.toString(16).padStart(2, '0')).join('');
}

// 按记录里的版本选择算法（新写入一律 v2；缺失/未知版本按 v1 处理以兼容存量数据）
async function hashForVersion(version, salt, password, iterations) {
  return Number(version) === PASSWORD_VERSION ? pbkdf2Hex(salt, password, iterations) : sha256Hex(salt, password);
}

async function getPasswordMeta(key) {
  const raw = await TEXTDB.get(passwordKey(key));
  if (!raw) return null;
  try { return JSON.parse(raw); } catch { return null; }
}

async function checkPassword(key, password, existingMeta) {
  if (!password) return false;
  const meta = existingMeta || await getPasswordMeta(key);
  if (!meta) return false;
  const hash = await hashForVersion(meta.v, meta.s, password, meta.i);
  if (!constantTimeEqual(hash, meta.h)) return false;
  // v1 → v2 透明升级：只在密码校验通过后执行，复用原盐，并记录时间戳
  // （升级失败不影响本次校验结果——密码已验证正确，不该因存储问题拒绝用户）
  if (Number(meta.v) !== PASSWORD_VERSION) {
    try {
      const upgraded = {h: await pbkdf2Hex(meta.s, password), s: meta.s, v: PASSWORD_VERSION, i: PBKDF2_ITERATIONS, u: Date.now()};
      await TEXTDB.put(passwordKey(key), JSON.stringify(upgraded));
    } catch (_) { /* ignore */ }
  }
  return true;
}

async function setPasswordMeta(key, password) {
  if (String(password).length < 4 || String(password).length > 128) throw new Error('Password must be 4-128 characters');
  const salt = generateSalt();
  const hash = await pbkdf2Hex(salt, password);
  await TEXTDB.put(passwordKey(key), JSON.stringify({h: hash, s: salt, v: PASSWORD_VERSION, i: PBKDF2_ITERATIONS}));
}

async function removePasswordMeta(key) {
  await TEXTDB.delete(passwordKey(key));
}

async function verifyDeletePassword(key, inputPwd) {
  const meta = await getPasswordMeta(key);
  if (!meta) return null; // no password, proceed
  if (!inputPwd) return 'Password required';
  const hash = await hashForVersion(meta.v, meta.s, inputPwd, meta.i);
  if (!constantTimeEqual(hash, meta.h)) return 'Incorrect password';
  return null; // verified OK（此处不做迁移：密码正确时随后即删除元数据，升级无意义）
}

async function handleApi(context) {
  const { request } = context;
  const url = new URL(request.url);
  const path = url.pathname;
  // KV 实例已在 onRequest 入口从 context.env.TEXTDB 注入到全局

  if (request.method === 'OPTIONS') return new Response(null, {status: 204, headers: CORS});

  try {
    if (request.method === 'POST') {
      let key, value, params = {};
      const ct = (request.headers.get('content-type') || '').toLowerCase();
      if (path === '/update/' || path === '/update' || path === '/api/update') {
        params = {};
        if (ct.includes('json')) params = await request.json();
        else {
          const fd = await request.formData();
          params = Object.fromEntries(fd.entries());
        }
        key = (params.key || '').trim();
        value = params.value;
      } else {
        key = path.split('/').pop();
        value = ct.includes('json') ? await request.json().then(v => typeof v === 'string' ? v : JSON.stringify(v)) : await request.text();
        params.password = request.headers.get('X-Password') || '';
      }
      if (!key || !/^[0-9a-zA-Z_]{1,512}$/.test(key)) return new Response(JSON.stringify({status:0, error:'Invalid Key'}), {status:400, headers: {...CORS, 'Content-Type':'application/json'}});

      // --- Delete path (empty value) ---
      if (!value) {
        const pwdErr = await verifyDeletePassword(key, request.headers.get('X-Password') || params.password || '');
        if (pwdErr) return new Response(JSON.stringify({status:0, error: pwdErr}), {status:400, headers: {...CORS, 'Content-Type':'application/json'}});
        const oldVal = await TEXTDB.get(kvKey(key));
        await TEXTDB.delete(kvKey(key));
        try { await removePasswordMeta(key); } catch (_) { /* non-critical */ }
        try { if (oldVal) { const s = '__stats_size__'; await TEXTDB.put(s, String(Math.max(0, Number(await TEXTDB.get(s) || '0') - byteLen(oldVal)))); } } catch (_) { /* non-critical */ }
        return new Response(JSON.stringify({status:1, data:{key, action:'deleted'}}), {headers: {...CORS, 'Content-Type':'application/json'}});
      }

      // --- Write/Update path ---
      const MAX_VALUE_SIZE = 5 * 1024 * 1024; // 5 MiB（实测 KV 单值上限 5,242,880 B）
      const valueStr = typeof value === 'string' ? value : JSON.stringify(value);
      if (byteLen(valueStr) > MAX_VALUE_SIZE) {
        return new Response(JSON.stringify({status:0, error:'Value too large (max 5 MiB)'}), {status:413, headers: {...CORS, 'Content-Type':'application/json'}});
      }

      const inputPwd = params.password || request.headers.get('X-Password') || '';
      const newPwd = params.new_password;
      const existingMeta = await getPasswordMeta(key);

      if (existingMeta) {
        // Key has password — verify before allowing update
        if (!inputPwd) return new Response(JSON.stringify({status:0, error:'Password required'}), {status:400, headers: {...CORS, 'Content-Type':'application/json'}});
        if (!(await checkPassword(key, inputPwd, existingMeta))) return new Response(JSON.stringify({status:0, error:'Incorrect password'}), {status:400, headers: {...CORS, 'Content-Type':'application/json'}});
        // Password correct — defer password change/removal until after data write succeeds
      } else {
        // Key has no password — first-time setup if password provided
        if (inputPwd) {
          if (String(inputPwd).length < 4 || String(inputPwd).length > 128) {
            return new Response(JSON.stringify({status:0, error:'Password must be 4-128 characters'}), {status:400, headers: {...CORS, 'Content-Type':'application/json'}});
          }
          await setPasswordMeta(key, inputPwd);
        }
      }

      // Validate new password length before data write (consistent 400, not 500 from setPasswordMeta)
      if (existingMeta && newPwd !== undefined && newPwd !== null && newPwd !== '') {
        if (String(newPwd).length < 4 || String(newPwd).length > 128) {
          return new Response(JSON.stringify({status:0, error:'Password must be 4-128 characters'}), {status:400, headers: {...CORS, 'Content-Type':'application/json'}});
        }
      }

      const oldVal = await TEXTDB.get(kvKey(key));
      await TEXTDB.put(kvKey(key), value);

      // Password change/removal after data write succeeds
      if (existingMeta && newPwd !== undefined && newPwd !== null) {
        if (newPwd === '') {
          try { await removePasswordMeta(key); } catch (_) { /* non-critical */ }
        } else {
          try { await setPasswordMeta(key, newPwd); } catch (_) { /* non-critical: password pre-validated, should not fail */ }
        }
      }
      try {
        const today = new Date().toISOString().slice(0, 10);
        const wKey = '__writes__' + today;
        await TEXTDB.put(wKey, String(Number(await TEXTDB.get(wKey) || '0') + 1));
        const newBytes = byteLen(valueStr), oldBytes = oldVal ? byteLen(oldVal) : 0;
        if (newBytes !== oldBytes) { const s = '__stats_size__'; await TEXTDB.put(s, String(Math.max(0, Number(await TEXTDB.get(s) || '0') + newBytes - oldBytes))); }
      } catch (_) { /* non-critical */ }
      return new Response(JSON.stringify({status:1, data:{key, url: url.origin + '/' + key}}), {headers: {...CORS, 'Content-Type':'application/json'}});
    }
    if (request.method === 'GET') {
      const key = path.split('/').pop();
      if (key && /^[0-9a-zA-Z_]{1,512}$/.test(key)) {
        const val = await TEXTDB.get(kvKey(key));
        return new Response(val || '', {headers: {...CORS, 'Content-Type': 'text/plain; charset=utf-8'}});
      }
    }
    if (request.method === 'DELETE') {
      const key = path.split('/').pop();
      if (!key || !/^[0-9a-zA-Z_]{1,512}$/.test(key)) return new Response(JSON.stringify({status:0, error:'Invalid Key'}), {status:400, headers: {...CORS, 'Content-Type':'application/json'}});
      const pwdErr = await verifyDeletePassword(key, request.headers.get('X-Password') || '');
      if (pwdErr) return new Response(JSON.stringify({status:0, error: pwdErr}), {status:400, headers: {...CORS, 'Content-Type':'application/json'}});
      const oldVal = await TEXTDB.get(kvKey(key));
      await TEXTDB.delete(kvKey(key));
      try { await removePasswordMeta(key); } catch (_) { /* non-critical */ }
      try { if (oldVal) { const s = '__stats_size__'; await TEXTDB.put(s, String(Math.max(0, Number(await TEXTDB.get(s) || '0') - byteLen(oldVal)))); } } catch (_) { /* non-critical */ }
      return new Response(JSON.stringify({status:1, data:{key, action:'deleted'}}), {headers: {...CORS, 'Content-Type':'application/json'}});
    }
    return new Response(JSON.stringify({status:0, error:'Not Found'}), {status:404, headers: {...CORS, 'Content-Type':'application/json'}});
  } catch (e) {
    return new Response(JSON.stringify({status:0, error: e.message}), {status:500, headers: {...CORS, 'Content-Type':'application/json'}});
  }
}

export async function onRequest(context) {
  const { request } = context;
  // EdgeOne Pages KV 绑定注入到 context.env（非全局变量），兼容旧代码的全局 TEXTDB 引用
  if (context.env && context.env.TEXTDB) globalThis.TEXTDB = context.env.TEXTDB;
  const url = new URL(request.url);
  const path = url.pathname;

  // OPTIONS 预检（所有路径）
  if (request.method === 'OPTIONS') return new Response(null, {status: 204, headers: CORS});

  // HTML 渲染路由 /p/{key}
  if (request.method === 'GET' && path.startsWith('/p/')) {
    const key = path.slice(3);
    if (key && /^[0-9a-zA-Z_]{1,512}$/.test(key)) {
      const val = await TEXTDB.get(kvKey(key));
      if (val === null) {
        return new Response('Not Found', {status: 404, headers: CORS});
      }
      return new Response(val, {headers: {...HTML_SECURITY_HEADERS, ...CORS}});
    }
    return new Response('Invalid Key', {status: 400, headers: CORS});
  }

  // 文件路由 /file/{ext}/{key} — 根据 ext 自动设置 Content-Type
  if (request.method === 'GET' && path.startsWith('/file/')) {
    const rest = path.slice(6); // 'js/mykey'
    const slashIdx = rest.indexOf('/');
    if (slashIdx > 0) {
      const ext = '.' + rest.slice(0, slashIdx);
      const key = rest.slice(slashIdx + 1);
      if (ext === '.html' || ext === '.svg') {
        return new Response('Use /p/ for HTML/SVG rendering', {status: 400, headers: CORS});
      }
      if (key && /^[0-9a-zA-Z_]{1,512}$/.test(key)) {
        const val = await TEXTDB.get(kvKey(key));
        if (val === null) {
          return new Response('Not Found', {status: 404, headers: CORS});
        }
        const ct = getMimeType(ext);
        const ctFinal = ct.includes('charset') ? ct : ct + '; charset=utf-8';
        const filename = key + ext;
        return new Response(val, {headers: {...CORS, 'Content-Type': ctFinal, 'X-Content-Type-Options': 'nosniff', 'Content-Disposition': 'attachment; filename="' + filename + '"'}});
      }
    }
    return new Response('Invalid Key', {status: 400, headers: CORS});
  }

  // Markdown 渲染路由 /md/{key} — 返回 SPA，前端自行解析渲染
  if (request.method === 'GET' && path.startsWith('/md/')) {
    const key = path.slice(4);
    if (key && /^[0-9a-zA-Z_]{1,512}$/.test(key)) {
      return new Response(STATIC_FILES['/index.html'], {
        headers: {'Content-Type': 'text/html; charset=utf-8', ...CORS}
      });
    }
    return new Response('Invalid Key', {status: 400, headers: CORS});
  }

  // 统计路由（仅 GET）
  if (request.method === 'GET' && (path === '/stats' || path === '/stats/')) {
    let totalKeys = 0, totalSize = 0, writesToday = 0, scannedAll = true, diag = '';
    // 1) list 分页统计 key 数（独立 try，失败不致命）
    try {
      let cursor;
      const MAX_SCAN_KEYS = 5000;
      while (true) {
        const opts = { prefix: KV_PREFIX, limit: 256 };
        if (cursor) opts.cursor = cursor;
        const result = await TEXTDB.list(opts);
        const keys = (result && result.keys) || [];
        totalKeys += keys.length;
        if (totalKeys >= MAX_SCAN_KEYS) { scannedAll = false; break; }
        const done = result.complete || !result.cursor;
        if (done) break;
        cursor = result.cursor;
      }
    } catch (e) { diag += 'list:' + (e && e.message || e) + '; '; }
    // 2) 计数器（独立 try）
    try {
      const today = new Date().toISOString().slice(0, 10);
      writesToday = Number(await TEXTDB.get('__writes__' + today) || '0');
    } catch (e) { diag += 'writes:' + (e && e.message || e) + '; '; }
    try {
      totalSize = Number(await TEXTDB.get('__stats_size__') || '0');
    } catch (e) { diag += 'size:' + (e && e.message || e) + '; '; }
    const payload = {status:1, data:{totalKeys, totalSize, writesToday, scannedAll}};
    if (diag) payload.diag = diag;
    return new Response(JSON.stringify(payload), {headers:{'Content-Type':'application/json', ...CORS}});
  }

  // KV 测试路由
  if (path === '/test-kv' || path === '/test-kv/') {
    try {
      // 按官方文档：直接使用全局变量 TEXTDB
      const val = await TEXTDB.get(kvKey('test_key'));
      let count = Number(val || '0') + 1;
      await TEXTDB.put(kvKey('test_key'), String(count));
      return new Response(JSON.stringify({status:'ok', count:count, message:'KV works!'}), {headers:{'Content-Type':'application/json', ...CORS}});
    } catch (e) {
      return new Response(JSON.stringify({status:'error', error: e && e.message ? e.message : String(e)}), {status:500, headers:{'Content-Type':'application/json', ...CORS}});
    }
  }

  // favicon — 返回 204，避免浏览器自动请求产生 404
  if (request.method === 'GET' && path === '/favicon.ico') {
    return new Response(null, {status: 204, headers: CORS});
  }

  if (path === '/' || path === '/index.html') {
    const requestUA = request.headers.get('User-Agent') || '';
    const respHeaders = {'Content-Type': 'text/html; charset=utf-8', 'Vary': 'User-Agent', ...CORS};
    if (isAiCrawler(requestUA)) {
      respHeaders['Cache-Control'] = 'no-cache, private';
    }
    return new Response(STATIC_FILES['/index.html'], {headers: respHeaders});
  }
  if (STATIC_FILES[path]) {
    return new Response(STATIC_FILES[path], {headers: {'Content-Type': getMimeType(path), ...CORS}});
  }
  return handleApi(context);
}